// src/components/pages/Home.js
import React from "react";
import { motion } from "framer-motion";
import { useNavigate } from "react-router-dom";
import PageWrapper from "../PageWrapper";

const Home = () => {
  const navigate = useNavigate();

  return (
    <PageWrapper>
      {/* Animated Gradient Background */}
      <div className="flex flex-col items-center justify-center min-h-screen px-6 relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-full bg-gradient-to-br from-indigo-400 via-purple-300 to-pink-300 animate-gradient-background -z-10"></div>

        {/* Heading */}
        <motion.h1
          initial={{ y: -40, opacity: 0 }}
          animate={{ y: 0, opacity: 1 }}
          transition={{ duration: 0.8 }}
          className="text-5xl md:text-6xl font-extrabold text-white mb-12 text-center"
          style={{ fontFamily: "'Poppins', 'Inter', sans-serif", textShadow: "0 2px 8px rgba(0,0,0,0.3)" }}
        >
          Welcome Back!
        </motion.h1>

        {/* Cards / Buttons */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-12 w-full max-w-5xl">
          
          {/* Interview Card */}
          <motion.div
            whileHover={{ scale: 1.05, boxShadow: "0 15px 40px rgba(0,0,0,0.25)" }}
            className="cursor-pointer bg-white rounded-3xl shadow-xl p-12 flex flex-col items-center justify-center transition-all"
            onClick={() => navigate("/interview")}
          >
            <h2 className="text-3xl font-bold text-indigo-600 mb-4">Interview</h2>
            <p className="text-gray-700 text-center text-lg mb-6">
              Record your mock interview and get personalized AI feedback.
            </p>
            <button className="bg-indigo-600 hover:bg-indigo-700 text-white font-semibold px-8 py-3 rounded-full transition-all duration-300 shadow-md">
              Start Interview
            </button>
          </motion.div>

          {/* Practice Questions Card */}
          <motion.div
            whileHover={{ scale: 1.05, boxShadow: "0 15px 40px rgba(0,0,0,0.25)" }}
            className="cursor-pointer bg-white rounded-3xl shadow-xl p-12 flex flex-col items-center justify-center transition-all"
            onClick={() => navigate("/practice")}
          >
            <h2 className="text-3xl font-bold text-pink-500 mb-4">Practice Questions</h2>
            <p className="text-gray-700 text-center text-lg mb-6">
              Improve your skills by practicing common interview questions.
            </p>
            <button className="bg-pink-500 hover:bg-pink-600 text-white font-semibold px-8 py-3 rounded-full transition-all duration-300 shadow-md">
              Start Practicing
            </button>
          </motion.div>
        </div>
      </div>
    </PageWrapper>
  );
};

export default Home;
